!function(e){function i(i){for(var t,n,o=i[0],m=i[1],d=i[2],s=0,g=[];s<o.length;s++)n=o[s],Object.prototype.hasOwnProperty.call(p,n)&&p[n]&&g.push(p[n][0]),p[n]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(c&&c(i);g.length;)g.shift()();return a.push.apply(a,d||[]),r()}function r(){for(var e,i=0;i<a.length;i++){for(var r,n=a[i],o=!0,m=1;m<n.length;m++)r=n[m],0!==p[r]&&(o=!1);o&&(a.splice(i--,1),e=t(t.s=n[0]))}return e}function t(i){if(n[i])return n[i].exports;var r=n[i]={i:i,l:!1,exports:{}};return e[i].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var n={},p={58:0},a=[];t.m=e,t.c=n,t.d=function(e,i,r){t.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,i){if(1&i&&(e=t(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var n in e)t.d(r,n,function(i){return e[i]}.bind(null,n));return r},t.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(i,"a",i),i},t.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=i,o=o.slice();for(var d=0;d<o.length;d++)i(o[d]);var c=m;a.push([236,0]),r()}({236:function(e,i,r){"use strict";r.r(i);var t=r(0);Object(t.a)("de","army",r(237),r(1))},237:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"MG42机枪","description":"<p>MG42机枪是二战中德军使用的一种极为出色的通用机枪，与MG34机枪相比，它不但使用材料少，造价便宜，制作工艺简单，更便于保养与使用，而且性能也有一定提高，特别是它的最高射速达到了1500发/秒，即每秒25发，射击时会形成密集的火力，人体一旦中弹，则会被多颗子弹瞬间穿过，造成严重的杀伤， 在高速射击时，连成一片的枪声会形成布匹撕裂（响如钢锯）的恐怖声音，因此使人感到闻风丧胆；在二战战场上美军称之为“希特勒电锯”，而苏军则称称之为“亚麻布剪刀”。</p><p>MG42机枪在1942年开始量产，二战期间，共生产了42万3千多挺；该机枪是德军步兵进攻与防御的核心武器，1943年，该机枪在非洲战场第一次投入战斗，以后则在二战欧洲东、西线战场上大显身手，到了二战结束后，MG42机枪仍是西德国防军的核心步兵武器。</p><p>MG42机枪的缺点是：射击精度一般，在射速过高时，很快会使枪管过热而要更换枪管，在激烈的战斗中，枪管更换时造成的火力缺失，会对部队及自身带来极大的危险。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwMG42_11.jpg","description":"<h6>MG42机枪</h6><p></p><p>技术数据：</p><p>口径：7.92毫米；</p><p>枪全长：1219毫米，枪管长：533毫米，枪全重：11.57千克；</p><p>最大射速：1500发/分钟（正常射速：1200发/分钟）；枪口初速：755米/秒；</p><p>有效射程：2000米；</p><p>弹容量与供弹方式：50/250发弹链。</p>","caption":""}],"part2title":"战场上的MG42机枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwMG42_21.jpg","description":"二战战场上肩扛MG42机枪的德军机枪手。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_22.jpg","description":"二战战场上，德军一挺MG42机枪正在射击中，地上遗留了一堆射击后的子弹壳。由于MG42机枪射速很高，因此子弹消耗得特别快，因此德军要求机枪手要控制在600发/分钟射速上下，以免造成弹药不足，以及枪管过热。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_23.jpg","description":"二战战场上，一名德军MG42机枪手满怀信心地注视前方，图中可清楚看到MG42机枪的外部结构。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_24.jpg","description":"二战战场上，德军一挺正在射击的MG42机枪。无论是在东线或西线战场，MG42机枪是德军步兵能完全压制住对手的武器。盟军内部甚至告诫士兵，遭遇德军的MG42机枪射击时，一定要迅速隐藏好自己。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_25.jpg","description":"1944年6月，西线战场，在法国诺曼底地区奥马尔海滩防御作战的德军352步兵师的MG42机枪手。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_26.jpg","description":"绘画：1944年6月，西线战场法国诺曼底地区奥马尔海滩，正与登陆盟军作战的德军，一挺MG42机枪正在猛烈射击。据传：在WN62碉堡中一名德军机枪手用MG42机枪打出12000发子弹，射杀了上千名美军（资料记载：这是当年的德国士兵海恩.塞弗莱在采访中回答的）。但实际上，在整个奥马尔海滩登陆战中，美军阵亡与负伤共2400多人，而德军防守海滩的部队拥有85挺机枪，因此光是一挺机枪是不可能有此战绩的，可知该名德军应是言过其实了。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_27.jpg","description":"1945年，东线战场德国本土，一个德军MG42机枪组正在奥得河沿岸防御，此时，苏联白俄罗斯第一方面军在朱可夫元帅率领下正在抢攻奥得河桥头堡。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_28.jpg","description":"1943年，东线苏联战场，一名德军MG42机枪手正以一辆烧毁的卡车作掩护，为德军步兵的进攻提供火力支援，图上方有一辆已被摧毁的苏军T-34坦克。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_29.jpg","description":"1944年8月，东线战场波兰华沙城附近，正在紧张地作战斗戒备的德国武装党卫军第3“骷髅”装甲师的一个MG42机枪组。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_30.jpg","description":"二战东线战场，在废墟中的一个德军MG42重机枪组阵地，机枪正在猛烈射击中，战斗十分激烈，三名机枪组成员都十分紧张，由于射速很高，散落的子弹壳激起了大量烟尘。在苏联战场恶劣环境和风雪低温气候条件下，德军的MG42机枪仍能保持其强悍的战斗能力，因此深受德军步兵的喜爱。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_31.jpg","description":"二战东线战场，德军一个MG42重机枪组正在作战斗戒备。图左胸前挂着一个望远镜的德军专门负责观察与指挥射击。MG42重机枪有近2000米的有效射程，一般会在1000米外就会开火射击，因此机枪组一般都会有一个负责观察目标与指挥射击的人员。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_32.jpg","description":"1943年3月，东线苏联战场哈尔科夫，纳粹德国武装党卫军的一个MG42机枪组正随时准备投入战斗，一名德军正用望远镜观察着前方战况。同年2月，苏军通过强攻收复了哈尔科夫，但到了3月，德军在曼施坦因的率领下进行了反击，经过激烈的巷战争夺，德军在3月中旬又重新攻占了哈尔科夫城。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_33.jpg","description":"二战西线战场，防守在“大西洋壁垒”海岸的德军一个MG42重机枪组。","caption":""},{"image":"imgs/de/army/de_army_iwMG42_34.jpg","description":"二战后期战场上的一个德军MG42机枪组，机枪射手作出了瞄准射击姿态；为了防范苏军坦克进攻，机枪旁还放置了一枚“铁拳”反坦克榴弹发射器。","caption":""}]}')}});